UPDATE "ContentEntity"
SET
  "shortContentDraftZH" = '结合老网站“科学——生物”与国际课程语境整理的课程样本，突出实验、探究与学术表达。',
  "shortContentDraftEN" = 'A course sample shaped from the legacy biology and international-program framing, focused on lab work, inquiry, and scientific communication.',
  "shortContentPublishedZH" = '结合老网站“科学——生物”与国际课程语境整理的课程样本，突出实验、探究与学术表达。',
  "shortContentPublishedEN" = 'A course sample shaped from the legacy biology and international-program framing, focused on lab work, inquiry, and scientific communication.',
  "contentDraftZH" = $$
{"root":{"props":{"title":"AP 生物"},"type":"root"},"content":[{"type":"SectionHeroConfig","props":{"id":"course-24-hero","eyebrow":"课程介绍","title":"把实验、问题意识和学术写作真正做深","description":"这门课程结合了老网站课程建设中的“科学——生物”线索和当前高中项目对学术挑战的要求，适合希望在生命科学方向持续深入的学生。","primaryLabel":"查看高中项目页","primaryLink":"/zh/academics/high-school","secondaryLabel":"回到课程栏目","secondaryLink":"/zh/academics/high-school","tone":"dark"}},{"type":"SectionIntroConfig","props":{"id":"course-24-intro","eyebrow":"课程导语","title":"不是只记知识点，而是学会像科学学习者那样工作","description":"课程强调实验设计、数据分析、概念建模与学术表达。学生需要在理解生物学核心概念的同时，逐步形成更严谨的研究与沟通方式。"}},{"type":"PathwayStepsConfig","props":{"id":"course-24-steps","eyebrow":"学习路径","title":"学生通常会这样进入并完成这门课","steps":[{"title":"建立核心概念","description":"通过细胞、生物体系统、遗传与生态等主题建立完整框架。"},{"title":"进入实验与数据","description":"在实验、观察和记录中学习如何提出问题、处理变量并解释结果。"},{"title":"形成学术表达","description":"把图表、证据与文字论证连接起来，让理解能够被清晰表达出来。"},{"title":"面向后续发展","description":"课程为后续更高阶的生命科学学习、研究项目和大学申请准备学术基础。"}]}}],"zones":{}}
$$,
  "contentDraftEN" = $$
{"root":{"props":{"title":"AP Biology"},"type":"root"},"content":[{"type":"SectionHeroConfig","props":{"id":"course-24-hero","eyebrow":"Course","title":"Take experiments, inquiry, and academic writing seriously","description":"This course combines the legacy site’s biology curriculum thread with the current high school program’s academic expectations. It fits students who want to go deeper in the life sciences.","primaryLabel":"See high school landing page","primaryLink":"/en/academics/high-school","secondaryLabel":"Back to courses","secondaryLink":"/en/academics/high-school","tone":"dark"}},{"type":"SectionIntroConfig","props":{"id":"course-24-intro","eyebrow":"Overview","title":"Learn to work like a scientific learner, not just memorize content","description":"The course emphasizes experiment design, data interpretation, concept modeling, and academic communication. Students build both biological understanding and more rigorous habits of research and explanation."}},{"type":"PathwayStepsConfig","props":{"id":"course-24-steps","eyebrow":"Pathway","title":"How students typically move through the course","steps":[{"title":"Build core concepts","description":"Students form a coherent framework through themes such as cells, systems, genetics, and ecology."},{"title":"Work with data","description":"Labs and observation train students to ask questions, manage variables, and interpret evidence."},{"title":"Communicate clearly","description":"Charts, evidence, and writing are linked so scientific understanding becomes persuasive expression."},{"title":"Prepare for what is next","description":"The course supports future research, advanced study in life science, and stronger university readiness."}]}}],"zones":{}}
