UPDATE "ContentEntity"
SET
  "shortContentDraftZH" = CASE id
    WHEN 3 THEN '从技术与真实场景的关系出发，尝试用导航系统回应公共环境中的使用问题。'
    WHEN 4 THEN '围绕社会参与与校园公益展开，把同理心转成长期行动。'
    WHEN 5 THEN '把艺术展览、文本回应与公共叙事结合起来，形成跨学科项目表达。'
    WHEN 6 THEN '把农业场景、数据记录与实际问题判断连起来，强调可验证的解决思路。'
    WHEN 7 THEN '围绕性别与日常需求提出更直接的公共议题，让设计回应真实不便。'
    WHEN 8 THEN '从植物、生命与观察经验出发，让科学理解转化为更有温度的表达。'
  END,
  "shortContentDraftEN" = CASE id
    WHEN 3 THEN 'A project that explores how navigation tools can respond to real public-space needs.'
    WHEN 4 THEN 'A socially engaged project that turns empathy and service into sustained action.'
    WHEN 5 THEN 'A cross-disciplinary project connecting exhibition making, text response, and public narrative.'
    WHEN 6 THEN 'An agriculture-facing project built around observation, data, and practical problem solving.'
    WHEN 7 THEN 'A public-interest project responding to everyday needs through a gender-aware design lens.'
    WHEN 8 THEN 'A project that turns botanical observation and scientific curiosity into thoughtful expression.'
  END,
  "shortContentPublishedZH" = CASE id
    WHEN 3 THEN '从技术与真实场景的关系出发，尝试用导航系统回应公共环境中的使用问题。'
    WHEN 4 THEN '围绕社会参与与校园公益展开，把同理心转成长期行动。'
    WHEN 5 THEN '把艺术展览、文本回应与公共叙事结合起来，形成跨学科项目表达。'
    WHEN 6 THEN '把农业场景、数据记录与实际问题判断连起来，强调可验证的解决思路。'
    WHEN 7 THEN '围绕性别与日常需求提出更直接的公共议题，让设计回应真实不便。'
    WHEN 8 THEN '从植物、生命与观察经验出发，让科学理解转化为更有温度的表达。'
  END,
  "shortContentPublishedEN" = CASE id
    WHEN 3 THEN 'A project that explores how navigation tools can respond to real public-space needs.'
    WHEN 4 THEN 'A socially engaged project that turns empathy and service into sustained action.'
    WHEN 5 THEN 'A cross-disciplinary project connecting exhibition making, text response, and public narrative.'
    WHEN 6 THEN 'An agriculture-facing project built around observation, data, and practical problem solving.'
    WHEN 7 THEN 'A public-interest project responding to everyday needs through a gender-aware design lens.'
    WHEN 8 THEN 'A project that turns botanical observation and scientific curiosity into thoughtful expression.'
  END
WHERE id IN (3, 4, 5, 6, 7, 8);

UPDATE "ContentEntity"
SET
  "categoryZH" = CASE id
    WHEN 2 THEN '校园新闻'
    WHEN 10 THEN '校园生活'
    WHEN 21 THEN '学生策展'
    WHEN 44 THEN '项目式学习'
  END,
  "categoryEN" = CASE id
    WHEN 2 THEN 'Campus News'
    WHEN 10 THEN 'Campus Life'
    WHEN 21 THEN 'Student Curation'
    WHEN 44 THEN 'Project-Based Learning'
  END,
  "shortContentDraftZH" = CASE id
    WHEN 2 THEN '从认证现场、课堂观察与国际化办学角度讲述学校通过 CIS 再认证的重要意义。'
    WHEN 10 THEN '以社团超市为切口，集中呈现 BAID 社团生态、学生兴趣与校园活力。'
    WHEN 21 THEN '从《素食者》到生态女性主义，这篇文章把学生策展、阅读与公共讨论连接起来。'
    WHEN 44 THEN '围绕“无障碍发展未来星”培养计划，展现学校如何把真实社会问题带入学生项目学习。'
  END,
  "shortContentDraftEN" = CASE id
    WHEN 2 THEN 'A campus-news story about the school’s CIS re-accreditation, seen through evaluation, classrooms, and international-program development.'
    WHEN 10 THEN 'A campus-life story that uses the club fair to show BAID’s student communities, interests, and energy.'
    WHEN 21 THEN 'A student-curation story linking The Vegetarian, ecofeminism, exhibition making, and public dialogue.'
    WHEN 44 THEN 'A project-based learning story about how accessibility and real social needs are brought into student project work.'
  END,
  "shortContentPublishedZH" = CASE id
    WHEN 2 THEN '从认证现场、课堂观察与国际化办学角度讲述学校通过 CIS 再认证的重要意义。'
    WHEN 10 THEN '以社团超市为切口，集中呈现 BAID 社团生态、学生兴趣与校园活力。'
    WHEN 21 THEN '从《素食者》到生态女性主义，这篇文章把学生策展、阅读与公共讨论连接起来。'
    WHEN 44 THEN '围绕“无障碍发展未来星”培养计划，展现学校如何把真实社会问题带入学生项目学习。'
  END,
  "shortContentPublishedEN" = CASE id
    WHEN 2 THEN 'A campus-news story about the school’s CIS re-accreditation, seen through evaluation, classrooms, and international-program development.'
    WHEN 10 THEN 'A campus-life story that uses the club fair to show BAID’s student communities, interests, and energy.'
    WHEN 21 THEN 'A student-curation story linking The Vegetarian, ecofeminism, exhibition making, and public dialogue.'
    WHEN 44 THEN 'A project-based learning story about how accessibility and real social needs are brought into student project work.'
  END
WHERE id IN (2, 10, 21, 44);

